import { mapState } from "vuex";
import {
  ensureSetShow,
  hotWordsAddApi,
  hotWordsListApi,
  wordsSetShow,
  hotWordsInfoApi
} from "@/api/product";
import uploadPictures from "@/components/uploadPictures";
export default {
  name: "ensure",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      columns1: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "热词",
          slot: "name",
          minWidth: 100,
        },
        {
          title: "是否显示",
          slot: "is_show",
          minWidth: 100,
        },
        {
          title: "排序",
          key: "sort",
          minWidth: 100,
        },
        {
          title: "创建时间",
          key: "add_time",
          minWidth: 130,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 120,
        },
      ],
      hotWordsForm: {
        page: 1,
        limit: 15,
        name: "",
      },
      list: [],
      total: 0,
      modals:false,
      form: {
        name: '',
        color: '#666',
        bg_color: '#f5f5f5',
        border_color:'',
        sort: 0,
        is_show: 1,
        icon: '',
        is_search: 0,
      },
      checkSelect: [],
      modalPic: false,
      rules: {
        name: [
          { required: true, message: '请输入热词名称', trigger: 'blur' },
          { min: 2, max: 6, message: '长度在 2 到 6 个字符', trigger: 'blur' },
        ],
      },
      isEdit:false,
      word_id:0
    };
  },
  components:{
    uploadPictures
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getList();
  },
  methods: {
    hotSearchs() {
      this.hotWordsForm.page = 1;
      this.list = [];
      this.getList();
    },
    showBnt(row) {
      let data = {
        id: row.id,
        is_show: row.is_show,
      };
      wordsSetShow(data).then((res) => {
        this.$Message.success(res.msg);
      })
      .catch((err) => {
        this.$Message.error(err.msg);
      });
    },
    // 添加
    add() {
      this.modals = true;
    },
    modalPicTap() {
      this.modalPic = true;
    },
    getPic(pic) {
      this.modalPic = false;
      this.form.icon = pic.att_dir;
    },
    delImage(){
      this.form.icon = '';
    },
    addWordsConfirm(){
      this.$refs.form.validate((valid) => {
        if (valid){
          hotWordsAddApi(this.isEdit ? this.word_id : 0,this.form).then(res=>{
            this.$Message.success(res.msg);
            this.modals = false;
            this.cancel();
            this.hotWordsForm.page = 1;
            this.getList();
          }).catch((res) => {
            this.$Message.error(res.msg);
          });
        }
      })
    },
    cancel(){
      this.form = {
        name: '',
        color: '#4f4f4f',
        bg_color: '#f4f4f4',
        border_color:'',
        sort: 0,
        is_show: 1,
        icon: '',
        is_search: 0,
      };
      this.isEdit = false;
    },
    // 单位列表
    getList() {
      this.loading = true;
      hotWordsListApi(this.hotWordsForm)
          .then((res) => {
            let data = res.data;
            this.list = data.list;
            this.total = data.count;
            this.loading = false;
          })
          .catch((err) => {
            this.loading = false;
            this.$Message.error(err.msg);
          });
    },
    pageChange(index) {
      this.hotWordsForm.page = index;
      this.getList();
    },
    //修改
    edit(id) {
      this.isEdit = true;
      this.word_id = id;
      hotWordsInfoApi(id).then(res=>{
        console.log(res.data);
        this.form = res.data;
        this.modals = true;
      })
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `product/words/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.hotWordsForm.page == 1;
          this.getList();
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
  },
};
